      return null;
    }

    Object id = findInjectableValueId(m);
    if (id == null) {
      return null;
    }

    return JacksonInject.Value.construct(id, Boolean.FALSE);
  }

  @Override
  public Object findInjectableValueId(AnnotatedMember m)
  {
